    <p v-if="error" class="mb-4 rounded bg-red-950 p-3 text-red-200">{{ error }}</p>
    <section class="panel mb-6 grid gap-3 md:grid-cols-4"><input v-model="filters.q" @input="load" placeholder="请输入游戏名/别名/开发商/发行商" /><select v-model="filters.source_type" @change="load"><option value="">所有类型</option><option value="rawg">PC / 主机游戏</option><option value="vndb">GAL / 视觉小说</option><option value="custom">自定义</option></select><select v-model="filters.play_status" @change="load"><option value="">所有状态</option><option v-for="(label,key) in statuses" :value="key">{{label}}</option></select><select v-model="filters.sort" @change="load"><option value="updated">最近更新</option><option value="created">最近添加</option><option value="rating">评分最高</option></select></section>
    <button class="mb-6 btn-muted inline-flex items-center gap-2" @click="toggleTagPanel"><svg v-if="!showTagPanel" class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M20 13 13 20H6a2 2 0 0 1-2-2v-7l7-7h7a2 2 0 0 1 2 2v7Z"/><circle cx="15.5" cy="8.5" r="1"/></svg><svg v-else class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>标签筛选<span v-if="selectedTags.length">({{selectedTags.length}})</span></button>
    <section v-if="games.length" class="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-5 xl:grid-cols-6"><article v-for="game in games" :key="game.id" class="group relative cursor-pointer overflow-hidden rounded-lg bg-panel shadow-lg" @click="openGame(game)"><img :src="cover(game.cover_url)" class="aspect-[2/3] w-full object-cover transition duration-300 group-hover:scale-105" /><div class="p-3"><h2 class="flex items-center justify-between gap-2"><span class="truncate font-semibold">{{displayTitle(game)}}</span><span v-if="game.file_size" class="shrink-0 text-xs font-normal text-slate-400">{{formatSize(game.file_size)}}</span></h2><div class="mt-2 flex justify-between text-xs text-slate-400"><span>{{ game.rating ? game.rating.toFixed(1) : '—' }}</span><span v-if="gameTags(game).length" class="truncate pl-2" :title="gameTags(game).join(' · ')">{{gameTags(game).slice(0,5).join(' · ')}}</span><span v-else>{{statuses[game.play_status]}}</span></div></div></article></section>
    <p v-else class="py-20 text-center text-slate-500">还没有游戏，点击右上角开始归档。</p>

    <section class="panel mt-6"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="font-semibold">扫描配置</h2><p class="mt-1 text-sm text-slate-400">下次增量扫描：{{nextScanAt}}</p><p v-if="scanRunning" class="mt-1 text-sm text-accent">扫描中：{{scanStatus.message}}</p></div><div class="flex gap-2"><button class="btn-muted" :disabled="scanRunning" @click="triggerScan()">{{scanRunning?'扫描中':'立即增量扫描'}}</button><button class="btn" :disabled="scanRunning" @click="triggerScan(true)">重建全量索引</button></div></div></section>

    <div v-if="showForm" class="fixed inset-0 z-10 overflow-y-auto bg-black/70 p-4"><section class="mx-auto my-4 max-w-4xl rounded-xl bg-panel p-5 md:my-10"><div class="mb-5 flex items-center justify-between"><div class="flex items-center gap-3"><h2 class="text-xl font-bold">{{active ? active.title : '添加游戏'}}</h2><button v-if="active" class="btn-muted" :disabled="refreshing[active.id] || isRefreshCooling(active)" @click="refreshMetadata(active)">{{refreshing[active.id]?'刷新中…':'刷新元数据'}}</button>
<div v-if="active" class="flex items-center gap-3">
  <span v-for="src in ['rawg','steam','vndb','dlsite']" :key="src" class="inline-flex items-center gap-1 text-xs" :class="sourceMatched(src) ? 'text-green-400' : 'text-red-400/70'">
    <span class="inline-flex h-4 w-4 items-center justify-center rounded-full text-[9px] font-bold" :class="refreshing[active.id] ? 'animate-spin rounded-full border-2 border-slate-500 border-t-accent' : (sourceMatched(src) ? 'bg-green-600 text-white' : 'bg-red-600/70 text-white')">
      <template v-if="!refreshing[active.id]">{{sourceMatched(src) ? '✓' : '✕'}}</template>
    </span>
    {{src}}
  </span>
</div></div><button class="btn-muted" @click="showForm=false">关闭</button></div><div v-if="active && form.resource_type !== 'none' && form.resource_url" class="mb-5 rounded bg-slate-800 p-3"><div class="flex flex-wrap items-center gap-2"><button class="btn" type="button" @click="downloadToPc">下载到本机</button><span v-if="form.file_size" class="text-sm text-slate-400">{{formatSize(form.file_size)}}</span><button v-if="form.resource_type === 'nas_cloud'" class="btn-muted" type="button" :disabled="transferTask && ['pending','running'].includes(transferTask.status)" @click="transferSubdir=form.title;showTransfer=true">转存到NAS本地</button></div><div v-if="transferTask" class="mt-3 text-sm"><p v-if="transferTask.status === 'completed'" class="font-semibold text-accent">下载完成</p><p v-else>{{transferTask.message}}</p><div v-if="['pending','running'].includes(transferTask.status)" class="mt-2 h-1 overflow-hidden rounded bg-slate-700"><div class="h-full bg-accent" :style="{width: transferTask.total_files ? (transferTask.copied_files/transferTask.total_files*100)+'%' : '0%'}"></div></div><p v-if="transferTask.total_files && transferTask.status !== 'completed'" class="mt-1">{{transferTask.copied_files}} / {{transferTask.total_files}} 个文件</p><div v-if="transferTask.status === 'completed'" class="mt-2 flex flex-wrap items-center gap-2"><span class="break-all">{{containerToNasPath(transferTask.target_path)}}</span><button class="btn-muted" type="button" @click="copyPath(transferTask.target_path)">复制路径</button></div></div></div>
      <div v-if="!active" class="mb-6 rounded-lg bg-slate-800 p-4"><h3 class="mb-3 font-semibold">自动刮削元数据</h3><div class="flex gap-2"><input v-model="scrape.q" @keyup.enter="scrapeSearch" placeholder="输入游戏名"/><select v-model="scrape.source_type" class="max-w-32"><option value="rawg">RAWG</option><option value="steam">Steam</option><option value="vndb">VNDB</option><option value="dlsite">DLsite</option></select><button class="btn whitespace-nowrap" :disabled="searching" @click="scrapeSearch">{{searching?'搜索中':'搜索'}}</button></div><div v-if="searchResults.length" class="mt-3 max-h-60 overflow-auto"><button v-for="item in searchResults" :key="item.source_id" class="block w-full border-b border-slate-700 text-left hover:bg-slate-700" @click="choose(item)">{{item.title}} <span class="text-slate-400">{{item.release_date || ''}}</span></button></div></div>
      <form class="grid gap-3 md:grid-cols-2" @submit.prevent="save"><label v-if="active">数据源<select v-model="form.source_type"><option value="rawg">rawg</option><option value="steam">steam</option><option value="vndb">vndb</option><option value="dlsite">dlsite</option><option value="custom">custom</option></select></label><label>游戏名<input :value="showOriginal ? (originalMetadata.title || form.title) : form.title" @input="form.title=$event.target.value" required></label><label>版本<input v-model="form.version" placeholder="如 v1.1.2"></label><label>入库时间<input :value="active ? new Date(active.created_at).toLocaleString() : ''" readonly></label><label>别名<input v-model="form.alias"></label><label>开发商<input v-model="form.developer"></label><label>发行商<input v-model="form.publisher"></label><label>发售日期<input v-model="form.release_date" type="date"></label><label>评分（0-100）<input v-model.number="form.rating" type="number" min="0" max="100" step="0.1"></label><label>标签来源<select v-model="tagSource" @change="changeTagSource"><option value="">自动</option><option value="steam">Steam</option><option value="rawg">RAWG</option><option value="vndb">VNDB</option><option value="dlsite">DLsite</option></select></label><label class="md:col-span-2">标签（逗号分隔）<input :value="displayTags" @input="form.tags=$event.target.value"></label><label>系列<input v-model="form.series"></label><label>资源类型<select v-model="form.resource_type"><option value="none">无</option><option value="nas_cloud">NAS挂载云盘</option><option value="nas_local">NAS本地游戏</option><option value="web_link">网盘链接</option></select></label><label>资源链接 / 路径<div class="flex gap-2"><input v-model="form.resource_url" :placeholder="form.resource_type === 'web_link' ? 'https://...' : form.resource_type === 'nas_local' ? '/vol/games/游戏名/' : '/vol/baidu/游戏名/'"><button class="btn-muted shrink-0" type="button" @click="copyResourcePath">复制路径</button></div></label><label>游玩状态<select v-model="form.play_status"><option v-for="(label,key) in statuses" :value="key">{{label}}</option></select></label><label class="md:col-span-2">封面来源<select v-model="coverSource" @change="changeCoverSource"><option value="auto">自动</option><option value="steam">Steam</option><option value="vndb">VNDB</option><option value="dlsite">DLsite</option><option value="rawg">RAWG</option><option value="custom">自定义</option></select><input v-if="coverSource === 'custom'" type="file" accept="image/jpeg,image/png" @change="uploadCover"></label><label class="md:col-span-2">简介<textarea :value="displayDescription" @input="form.description=$event.target.value" rows="4"></textarea></label><div class="flex gap-2 md:col-span-2"><button class="btn" type="submit">保存</button><button v-if="active" class="bg-red-700" type="button" @click="removeGame">删除</button></div></form>
      <section v-if="active" class="mt-7 border-t border-slate-700 pt-5"><div class="mt-4"><h3 class="mb-2 font-semibold">截图来源</h3><select v-model="form.screenshot_source" @change="changeScreenshotSource"><option value="">自动</option><option value="rawg">RAWG</option><option value="steam">Steam</option><option value="vndb">VNDB</option><option value="dlsite">DLsite</option><option value="custom">自定义</option></select><input v-if="form.screenshot_source==='custom'" class="mt-2" type="file" accept="image/png,image/jpeg" multiple @change="uploadScreenshot"></div><div v-if="screenshots.length" class="mt-5"><h3 class="mb-3 font-semibold">游戏截图</h3><div class="flex gap-3 overflow-x-auto pb-2"><div v-for="(url,index) in screenshots" :key="url" class="relative shrink-0"><button class="absolute right-1 top-1 z-10 h-7 w-7 rounded-full bg-slate-950/80" @click.stop="deleteScreenshot(index)">×</button><button class="p-0" @click="previewScreenshot=index"><img :src="url" class="h-36 w-60 rounded object-cover" alt="游戏截图"></button></div></div></div><p v-else class="mt-5 text-sm text-slate-500">暂无截图，可在上方「截图来源」选择 RAWG 获取，或点「刷新元数据」后重试</p><div v-if="form.resource_type !== 'none' && form.resource_url" class="mt-5"><p v-if="form.resource_type === 'web_link'" class="mt-3 text-sm text-slate-500">网盘链接不支持下载，请点击打开链接</p></div></section>
    </section></div>
    <div v-if="showSettings" class="fixed inset-0 z-10 overflow-y-auto bg-black/70 p-4"><section class="mx-auto my-4 max-w-4xl rounded-xl bg-panel p-5 md:my-10"><div class="mb-5 flex items-center justify-between"><h2 class="text-xl font-bold">系统设置</h2><button class="btn-muted" @click="showSettings=false">关闭</button></div><div class="mb-5 flex gap-2 overflow-x-auto"><button v-for="tab in [['scan','扫描设置'],['source','数据源'],['glossary','翻译术语表'],['about','关于']]" :class="settingsTab===tab[0]?'btn':'btn-muted'" @click="settingsTab=tab[0]">{{tab[1]}}</button></div><section v-if="settingsTab==='scan'" class="grid gap-3 md:grid-cols-2"><label class="flex items-center gap-2">定时同步<input v-model="systemSettings.scan_enable" type="checkbox" class="w-auto"></label><label>同步间隔<select v-model="systemSettings.scan_cron"><option value="0 3 * * *">每天凌晨3点</option><option value="0 */6 * * *">每6小时</option><option value="0 */12 * * *">每12小时</option><option value="0 * * * *">每小时</option><option :value="systemSettings.scan_cron">自定义 cron</option></select></label><label>云盘扫描根路径<input v-model="systemSettings.scan_root" placeholder="/vol/baidu/"></label><label>本地游戏扫描根路径<input v-model="systemSettings.local_game_root" placeholder="/vol/games/"></label><label>云盘转存默认下载路径<input v-model="systemSettings.download_dir" placeholder="/vol/download/game/"></label><p class="text-sm text-slate-400">下次扫描：{{nextScanAt}}</p><div class="flex gap-2 md:col-span-2"><button class="btn-muted" :disabled="scanRunning" @click="triggerScan()">立即增量扫描</button><button class="btn" :disabled="scanRunning" @click="triggerScan(true)">全量扫描</button></div></section><section v-else-if="settingsTab==='source'" class="grid gap-3 md:grid-cols-2"><label>RAWG API Key<input v-model="systemSettings.rawg_api_key" placeholder="请输入 RAWG API Key"></label><button class="btn-muted self-end" @click="testSettings('rawg')">测试连接</button><label>翻译 API<select v-model="systemSettings.translator_type"><option value="none">关闭</option><option value="tencent">腾讯翻译君</option></select></label><label class="flex items-center gap-2 self-end">自动翻译<input v-model="systemSettings.auto_translate" type="checkbox" class="w-auto"></label><template v-if="systemSettings.translator_type==='tencent'"><label>SecretId<input v-model="systemSettings.tencent_secret_id" placeholder="请输入 SecretId"></label><label>SecretKey<input v-model="systemSettings.tencent_secret_key" placeholder="请输入 SecretKey"></label><label>Region<input v-model="systemSettings.tencent_region" placeholder="ap-guangzhou"></label><button class="btn-muted self-end" @click="testSettings('translator')">测试翻译</button></template><div class="mt-4 rounded bg-slate-800 p-3"><h3 class="mb-2 font-semibold">游戏名数据源</h3><p class="mb-2 text-sm text-slate-400">拖动排序；至少保留一个启用的数据源。上方的数据源优先级更高</p><div class="space-y-2"><div v-for="source in sourcePriority" :key="source" draggable="true" class="flex items-center gap-3 rounded border border-slate-700 p-2" @dragstart="dragSource(source)" @dragover.prevent @drop="dropSource(source)"><span class="cursor-grab text-slate-400">☰</span><span class="font-medium capitalize">{{source}}</span><input v-model="sourceEnabled[source]" type="checkbox" class="ml-auto w-auto" @change="toggleSource(source)"></div></div></div><div class="mt-4 rounded bg-slate-800 p-3"><h3 class="mb-2 font-semibold">标签数据源</h3><p class="mb-2 text-sm text-slate-400">拖动排序；至少保留一个启用的数据源。上方的数据源优先级更高</p><div class="space-y-2"><div v-for="source in tagPriority" :key="source" draggable="true" class="flex items-center gap-3 rounded border border-slate-700 p-2" @dragstart="dragTagSource(source)" @dragover.prevent @drop="dropTagSource(source)"><span class="cursor-grab text-slate-400">☰</span><span class="font-medium capitalize">{{source}}</span><input v-model="tagEnabled[source]" type="checkbox" class="ml-auto w-auto" @change="toggleTagSource(source)"></div></div></div><div class="mt-4 rounded bg-slate-800 p-3"><h3 class="mb-2 font-semibold">封面数据源</h3><p class="mb-2 text-sm text-slate-400">拖动排序；至少保留一个启用的数据源。上方的数据源优先级更高</p><div class="space-y-2"><div v-for="source in coverPriority" :key="source" draggable="true" class="flex items-center gap-3 rounded border border-slate-700 p-2" @dragstart="dragCoverSource(source)" @dragover.prevent @drop="dropCoverSource(source)"><span class="cursor-grab text-slate-400">☰</span><span class="font-medium capitalize">{{source}}</span><input v-model="coverEnabled[source]" type="checkbox" class="ml-auto w-auto" @change="toggleCover(source)"></div></div></div><div class="mt-4 rounded bg-slate-800 p-3"><h3 class="mb-2 font-semibold">截图数据源</h3><p class="mb-2 text-sm text-slate-400">拖动排序；至少保留一个启用的数据源。上方的数据源优先级更高</p><div class="space-y-2"><div v-for="source in screenshotPriority" :key="source" draggable="true" class="flex items-center gap-3 rounded border border-slate-700 p-2" @dragstart="dragScreenshotSource(source)" @dragover.prevent @drop="dropScreenshotSource(source)"><span class="cursor-grab text-slate-400">☰</span><span class="font-medium capitalize">{{source}}</span><input v-model="screenshotEnabled[source]" type="checkbox" class="ml-auto w-auto" @change="toggleScreenshot(source)"></div></div></div>

</section><section v-else-if="settingsTab==='glossary'"><div class="mb-3 flex gap-2"><input v-model="glossaryQ" placeholder="搜索原文" @input="loadGlossary"><input v-model="glossaryCategory" placeholder="分类" @input="loadGlossary"></div><div class="mb-3 grid gap-2 md:grid-cols-4"><input v-model="glossaryDraft.source_text" placeholder="原文"><input v-model="glossaryDraft.target_text" placeholder="译文"><input v-model="glossaryDraft.category" placeholder="分类"><button class="btn" @click="saveGlossary">{{glossaryEditing?'保存':'新增'}}</button></div><div v-for="item in glossary" :key="item.id" class="flex items-center gap-2 border-b border-slate-700 py-2 text-sm"><span class="flex-1">{{item.source_text}}</span><span class="flex-1">{{item.target_text}}</span><span>{{item.category}}</span><button class="btn-muted" @click="Object.assign(glossaryDraft,item);glossaryEditing=item.id">编辑</button><button class="bg-red-700" @click="deleteGlossary(item.id)">删除</button></div><textarea v-model="glossaryBatch" class="mt-4" rows="4" placeholder='批量导入 JSON：[{"source_text":"Action","target_text":"动作","category":"tag"}]'></textarea><button class="btn mt-2" @click="importGlossary">批量导入</button>
<div class="mt-6 border-t border-slate-700 pt-4">
<h3 class="mb-3 text-lg font-bold">标签术语表（JSON，自动学习）</h3>
<p class="mb-3 text-sm text-slate-400">标签翻译优先查此表，查不到自动调用谷歌翻译并加入此表。可手动编辑补充。</p>
<div class="mb-3 flex gap-2"><input v-model="tagGlossaryQ" placeholder="搜索标签" @input="loadTagGlossary"><button class="btn-muted" @click="loadTagGlossary">搜索</button></div>
<div class="mb-3 grid gap-2 md:grid-cols-3"><input v-model="tagGlossaryDraft.source_text" placeholder="原文（日文）"><input v-model="tagGlossaryDraft.target_text" placeholder="译文（中文）"><button class="btn" @click="saveTagGlossaryItem">新增/更新</button></div>
<div class="max-h-96 overflow-y-auto"><div v-for="(value,key) in tagGlossary" :key="key" class="flex items-center gap-2 border-b border-slate-700 py-2 text-sm"><span class="flex-1">{{key}}</span><span class="flex-1">{{value}}</span><button class="bg-red-700" @click="deleteTagGlossaryItem(key)">删除</button></div></div>
<p class="mt-2 text-sm text-slate-500">共 {{Object.keys(tagGlossary).length}} 条</p>
</div></section><section v-else class="space-y-2 text-sm text-slate-300"><p>版本：1.3.0</p><p>技术栈：FastAPI · SQLAlchemy Async · SQLite · Vue 3</p><p>数据目录：/app/data/</p></section><div v-if="settingsTab==='scan'||settingsTab==='source'" class="mt-5"><button class="btn" @click="saveSettings">保存设置</button></div></section></div>
    <div v-if="showTransfer" class="fixed inset-0 z-20 flex items-center justify-center bg-black/70 p-4"><section class="w-full max-w-md rounded-xl bg-panel p-5"><h3 class="font-semibold">转存到 NAS 本地</h3><label class="mt-3 block">子目录名（可留空）<input v-model="transferSubdir" :placeholder="form.title"></label><div class="mt-4 flex justify-end gap-2"><button class="btn-muted" @click="showTransfer=false">取消</button><button class="btn" @click="startTransfer">确认转存</button></div></section></div>
    <div v-if="previewScreenshot >= 0" class="fixed inset-0 z-20 flex items-center justify-center bg-black/90 p-4" @click.self="previewScreenshot=-1"><button class="absolute left-4 text-4xl" @click="movePreview(-1)">‹</button><img :src="screenshots[previewScreenshot]" class="max-h-full max-w-full object-contain" alt="游戏截图预览"><button class="absolute right-4 text-4xl" @click="movePreview(1)">›</button></div>
  </main>
</template>